// Synthesises woven/knitted cloth at yarn level. Output: 8-bit RGB PPM (ffmpeg converts).
// Each fabric matches the garment's stated construction: plain, twill 3/1, basket (oxford), jersey knit.
import { writeFileSync } from 'node:fs'

const W = 1400, H = 1867

// --- value noise -----------------------------------------------------------
function mulberry(seed) { return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296 } }
function noiseField(w, h, seed) { const r = mulberry(seed), a = new Float32Array(w * h); for (let i = 0; i < a.length; i++) a[i] = r(); return a }
function sampleBilinear(a, w, h, x, y) {
  x = ((x % w) + w) % w; y = ((y % h) + h) % h
  const x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0
  const x1 = (x0 + 1) % w, y1 = (y0 + 1) % h
  const s = (u, v) => a[v * w + u]
  const t = (b) => b * b * (3 - 2 * b)
  const u = t(fx), v = t(fy)
  return (s(x0, y0) * (1 - u) + s(x1, y0) * u) * (1 - v) + (s(x0, y1) * (1 - u) + s(x1, y1) * u) * v
}

const hex = (c) => [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)]

// --- weave lift functions: is warp (vertical yarn) on top at cell (cx,cy)? --
const LIFT = {
  plain: (cx, cy) => (cx + cy) % 2 === 0,
  twill: (cx, cy) => (((cx - cy) % 4) + 4) % 4 !== 0,      // 3/1 right-hand twill, warp-faced
  basket: (cx, cy) => ((cx >> 1) + (cy >> 1)) % 2 === 0,   // 2x2 basket = oxford
}

function weave(spec) {
  const { warp, weft, yarn, seed, contrast = 1, slub = 1, name, weaveType } = spec
  const [wr, wg, wb] = hex(warp), [fr, fg, fb] = hex(weft)
  const n1 = noiseField(256, 256, seed), n2 = noiseField(64, 64, seed + 7)
  const cols = Math.ceil(W / yarn) + 2, rows = Math.ceil(H / yarn) + 2
  const rnd = mulberry(seed + 31)
  // per-yarn thickness + dye variation, the thing that makes real cloth not a grid
  const warpVar = Array.from({ length: cols }, () => ({ t: 0.82 + rnd() * 0.36, d: (rnd() - 0.5) * 0.16 * slub }))
  const weftVar = Array.from({ length: rows }, () => ({ t: 0.82 + rnd() * 0.36, d: (rnd() - 0.5) * 0.16 * slub }))
  const lift = LIFT[weaveType]
  const buf = Buffer.alloc(W * H * 3)
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const cx = Math.floor(x / yarn), cy = Math.floor(y / yarn)
      // yarn-local coordinate, wobbled so rows are not perfectly straight
      const wob = (sampleBilinear(n2, 64, 64, x * 0.02, y * 0.02) - 0.5) * yarn * 0.35
      const ux = ((x + wob) / yarn) % 1, uy = ((y - wob * 0.7) / yarn) % 1
      const warpTop = lift(cx, cy)
      const vw = warpVar[cx % cols], vf = weftVar[cy % rows]
      // cylindrical shading across the yarn that is on top
      const across = warpTop ? ux : uy
      const thick = warpTop ? vw.t : vf.t
      const edge = Math.min(1, Math.max(0, (0.5 - Math.abs(across - 0.5)) / (0.5 * thick)))
      const round = Math.sqrt(Math.max(0, edge)) * 0.9 + 0.1
      let shade = 0.55 + round * 0.62 * contrast
      // occlusion where the yarn dives under its neighbour
      const along = warpTop ? uy : ux
      shade *= 0.90 + 0.16 * Math.sin(Math.PI * along)
      // fibre fuzz + dye
      const fuzz = sampleBilinear(n1, 256, 256, x * 0.9, y * 0.9) - 0.5
      const drift = (sampleBilinear(n2, 64, 64, x * 0.006, y * 0.006) - 0.5) * 0.20
      const dye = 1 + (warpTop ? vw.d : vf.d) + drift
      const s = shade * dye + fuzz * 0.085
      const i = (y * W + x) * 3
      const [r, g, b] = warpTop ? [wr, wg, wb] : [fr, fg, fb]
      buf[i] = Math.max(0, Math.min(255, r * s))
      buf[i + 1] = Math.max(0, Math.min(255, g * s))
      buf[i + 2] = Math.max(0, Math.min(255, b * s))
    }
  }
  writeFileSync(`../public/cloth/${name}.ppm`, Buffer.concat([Buffer.from(`P6\n${W} ${H}\n255\n`), buf]))
  console.log('wrote', name)
}

// knit is loops, not interlacing: separate generator for the lambswool
function knit(spec) {
  const { yarnCol, melange, gauge, seed, name } = spec
  const [r0, g0, b0] = hex(yarnCol), [r1, g1, b1] = hex(melange)
  const n1 = noiseField(256, 256, seed), n2 = noiseField(64, 64, seed + 5)
  const gw = gauge, gh = gauge * 0.78
  const buf = Buffer.alloc(W * H * 3)
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const row = Math.floor(y / gh)
      const off = (row % 2) * gw * 0.5
      const ux = (((x + off) / gw) % 1), uy = (y / gh) % 1
      // a knit stitch reads as two legs of a V meeting at the bottom
      const legDist = Math.min(Math.abs(ux - 0.28 - uy * 0.18), Math.abs(ux - 0.72 + uy * 0.18))
      const legPlus = Math.min(legDist, Math.abs(ux - 0.28 - uy * 0.18 + 1), Math.abs(ux - 0.72 + uy * 0.18 - 1))
      const core = Math.max(0, 1 - legPlus / 0.22)
      const round = Math.sqrt(core)
      let shade = 0.42 + round * 0.72
      shade *= 0.88 + 0.20 * (1 - uy)               // loop rolls forward at the head
      const fuzz = sampleBilinear(n1, 256, 256, x * 1.3, y * 1.3) - 0.5
      const halo = sampleBilinear(n1, 256, 256, x * 0.35, y * 0.35) - 0.5   // brushed lambswool haze
      const drift = (sampleBilinear(n2, 64, 64, x * 0.007, y * 0.007) - 0.5) * 0.18
      const mel = Math.min(1, Math.max(0, sampleBilinear(n1, 256, 256, x * 0.5 + 40, y * 0.5) * 1.5 - 0.35))
      const s = shade * (1 + drift) + fuzz * 0.10 + halo * 0.13
      const i = (y * W + x) * 3
      buf[i] = Math.max(0, Math.min(255, (r0 * (1 - mel) + r1 * mel) * s))
      buf[i + 1] = Math.max(0, Math.min(255, (g0 * (1 - mel) + g1 * mel) * s))
      buf[i + 2] = Math.max(0, Math.min(255, (b0 * (1 - mel) + b1 * mel) * s))
    }
  }
  writeFileSync(`../public/cloth/${name}.ppm`, Buffer.concat([Buffer.from(`P6\n${W} ${H}\n255\n`), buf]))
  console.log('wrote', name)
}

// 12oz cotton canvas, indigo — the Chore Jacket. Heavy yarn, plain weave.
weave({ name: 'canvas-indigo', weaveType: 'plain', warp: '#2f4360', weft: '#38506f', yarn: 7.5, seed: 11, contrast: 1.0, slub: 1.3 })
// 13.5oz selvedge denim, rinse — the Straight Jean. Indigo warp over ecru weft, 3/1 twill.
weave({ name: 'denim-rinse', weaveType: 'twill', warp: '#2b3f61', weft: '#c9bfa8', yarn: 6.2, seed: 23, contrast: 1.15, slub: 1.6 })
// 140gsm oxford, pale blue — the Oxford Shirt. Fine 2x2 basket, coloured warp, white weft.
weave({ name: 'oxford-blue', weaveType: 'basket', warp: '#7f9bbd', weft: '#eef1f3', yarn: 5.0, seed: 41, contrast: 0.85, slub: 0.7 })
// lambswool, navy melange — the Lambswool Crew.
knit({ name: 'lambswool-navy', yarnCol: '#2c3446', melange: '#6b7488', gauge: 13, seed: 59 })
