function segDist(px, py, ax, ay, bx, by) {
  const vx = bx - ax, vy = by - ay, wx = px - ax, wy = py - ay
  const t = Math.max(0, Math.min(1, (wx * vx + wy * vy) / (vx * vx + vy * vy)))
  const dx = wx - t * vx, dy = wy - t * vy
  return Math.sqrt(dx * dx + dy * dy)
}
function knit(spec) {
  const { yarnCol, melange, gauge, seed, name } = spec
  const [r0, g0, b0] = hex(yarnCol), [r1, g1, b1] = hex(melange)
  const n1 = noiseField(256, 256, seed), n2 = noiseField(64, 64, seed + 5)
  const gw = gauge, gh = gauge * 0.86, halfW = 0.30
  const buf = Buffer.alloc(W * H * 3)
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const wob = (sampleBilinear(n2, 64, 64, x * 0.03, y * 0.03) - 0.5) * gauge * 0.22
