// Composites each garment from its own cloth: clipped panels with grain direction,
// drape shading, edge roundness, seams, topstitch, hardware. Output: RGBA PNG.
import { chromium } from 'playwright'
import { writeFileSync, readFileSync } from 'node:fs'
import { GARMENTS } from './garments.mjs'

const W = 1200, H = 1600
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: W, height: H } })

const cloth = {}
for (const g of Object.values(GARMENTS)) {
  if (!cloth[g.fabric]) cloth[g.fabric] = 'data:image/png;base64,' + readFileSync(`../public/cloth/${g.fabric}.png`).toString('base64')
}
await page.setContent('<canvas id="c" width="1200" height="1600"></canvas>')

const out = await page.evaluate(async ({ GARMENTS, cloth, W, H }) => {
  const imgs = {}
  await Promise.all(Object.entries(cloth).map(([k, src]) => new Promise((res) => {
    const i = new Image(); i.onload = () => { imgs[k] = i; res() }; i.src = src
  })))
  const c = document.getElementById('c'), ctx = c.getContext('2d')

  // Catmull-Rom through the authored points, so garment edges curve like cloth.
  const smooth = (pts, begin = true) => {
    const n = pts.length
    if (begin) ctx.beginPath()
    ctx.moveTo(pts[0][0], pts[0][1])
    const get = (i) => pts[(i % n + n) % n]
    for (let i = 0; i < n; i++) {
      const p0 = get(i - 1), p1 = get(i), p2 = get(i + 1), p3 = get(i + 2), t = 0.2
      ctx.bezierCurveTo(p1[0] + (p2[0] - p0[0]) * t, p1[1] + (p2[1] - p0[1]) * t,
        p2[0] - (p3[0] - p1[0]) * t, p2[1] - (p3[1] - p1[1]) * t, p2[0], p2[1])
    }
    ctx.closePath()
  }
  const unionPath = (g) => { ctx.beginPath(); for (const p of g.panels) smooth(p.path, false) }

  const results = {}
  for (const [key, g] of Object.entries(GARMENTS)) {
    ctx.clearRect(0, 0, W, H)
    const fabric = imgs[g.fabric]

    for (const p of g.panels) {
      ctx.save()
      smooth(p.path); ctx.clip()
      const xs = p.path.map((q) => q[0]), ys = p.path.map((q) => q[1])
      const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys)
      const cx = (x0 + x1) / 2, cy = (y0 + Math.max(...ys)) / 2
      // grain follows the cut piece: a sleeve carries a rotated warp
      ctx.translate(cx, cy); ctx.rotate((p.rot || 0) * 0.55); ctx.scale(g.scale, g.scale)
      const fw = 2200, fh = fw * fabric.height / fabric.width
      ctx.drawImage(fabric, -fw / 2 + (cx % 140) - 70, -fh / 2 + (cy % 180) - 90, fw, fh)
      ctx.setTransform(1, 0, 0, 1, 0, 0)
      smooth(p.path); ctx.clip()

      if (p.shade !== 1) {
        ctx.globalCompositeOperation = p.shade < 1 ? 'multiply' : 'screen'
        ctx.fillStyle = p.shade < 1
          ? `rgba(0,0,0,${(1 - p.shade) * 2.6})` : `rgba(255,255,255,${(p.shade - 1) * 1.7})`
        ctx.fillRect(0, 0, W, H)
        ctx.globalCompositeOperation = 'source-over'
      }
      // ribbing runs in visible columns of knit and purl
      if (p.rib) {
        for (let x = x0; x < x1; x += 11) {
          ctx.globalCompositeOperation = 'multiply'
          ctx.fillStyle = 'rgba(0,0,0,0.30)'; ctx.fillRect(x, 0, 4.5, H)
          ctx.globalCompositeOperation = 'screen'
          ctx.fillStyle = 'rgba(255,255,255,0.13)'; ctx.fillRect(x + 5.5, 0, 3, H)
        }
        ctx.globalCompositeOperation = 'source-over'
      }
      // drape: soft folds down the panel, a highlight riding each ridge
      const w = x1 - x0
      ctx.filter = 'blur(26px)'
      ctx.globalCompositeOperation = 'multiply'
      const folds = [[0.22, 0.5], [0.55, 0.34], [0.78, 0.42]]
      for (const [fx, amt] of folds) {
        const fxp = x0 + w * fx
        const grad = ctx.createLinearGradient(fxp - w * 0.18, 0, fxp + w * 0.18, 0)
        grad.addColorStop(0, 'rgba(255,255,255,0)')
        grad.addColorStop(0.5, `rgba(20,26,40,${0.30 * amt})`)
        grad.addColorStop(1, 'rgba(255,255,255,0)')
        ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H)
      }
      ctx.globalCompositeOperation = 'screen'
      for (const [fx] of folds) {
        const fxp = x0 + w * fx - w * 0.13
        const grad = ctx.createLinearGradient(fxp - w * 0.09, 0, fxp + w * 0.09, 0)
        grad.addColorStop(0, 'rgba(255,255,255,0)')
        grad.addColorStop(0.5, 'rgba(255,255,255,0.11)')
        grad.addColorStop(1, 'rgba(255,255,255,0)')
        ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H)
      }
      // edge roundness: cloth turns away from the light at the panel border
      ctx.globalCompositeOperation = 'multiply'
      ctx.filter = 'blur(14px)'
      ctx.strokeStyle = 'rgba(10,14,24,0.55)'; ctx.lineWidth = 30
      smooth(p.path); ctx.stroke()
      ctx.filter = 'none'; ctx.globalCompositeOperation = 'source-over'
      ctx.restore()
    }

    // seams, topstitching and hardware, clipped to the garment
    ctx.save()
    unionPath(g); ctx.clip()
    for (const s of (g.seams || [])) {
      ctx.beginPath(); s.d.forEach((q, i) => i ? ctx.lineTo(q[0], q[1]) : ctx.moveTo(q[0], q[1]))
      ctx.strokeStyle = 'rgba(8,12,20,0.45)'; ctx.lineWidth = s.w * 1.9; ctx.setLineDash([]); ctx.stroke()
      if (s.stitch) {
        ctx.strokeStyle = g.thread || 'rgba(226,230,236,0.42)'
        ctx.lineWidth = s.w * 0.85; ctx.setLineDash([7, 6]); ctx.stroke(); ctx.setLineDash([])
      }
    }
    for (const p of (g.pockets || [])) {
      const rect = () => {
        ctx.beginPath()
        if (p.arc) { ctx.moveTo(p.x, p.y); ctx.quadraticCurveTo(p.x + p.w / 2, p.y + p.h * 2.1, p.x + p.w, p.y) }
        else { ctx.moveTo(p.x, p.y); ctx.lineTo(p.x, p.y + p.h); ctx.lineTo(p.x + p.w, p.y + p.h); ctx.lineTo(p.x + p.w, p.y) }
      }
      if (!p.arc) { // a patch pocket sits proud of the body and casts a small shadow
        ctx.save(); ctx.filter = 'blur(7px)'; ctx.globalCompositeOperation = 'multiply'
        ctx.strokeStyle = 'rgba(8,12,20,0.5)'; ctx.lineWidth = 10; rect(); ctx.stroke(); ctx.restore()
      }
      rect()
      ctx.strokeStyle = 'rgba(8,12,20,0.42)'; ctx.lineWidth = 3.4; ctx.stroke()
      ctx.strokeStyle = g.thread || 'rgba(226,230,236,0.38)'
      ctx.lineWidth = 1.8; ctx.setLineDash([7, 6]); ctx.stroke(); ctx.setLineDash([])
    }
    for (const b of (g.buttons || [])) {
      const r = 15
      ctx.save(); ctx.filter = 'blur(4px)'; ctx.fillStyle = 'rgba(8,12,20,0.55)'
      ctx.beginPath(); ctx.arc(b[0] + 2, b[1] + 5, r, 0, 7); ctx.fill(); ctx.restore()
      const gr = ctx.createRadialGradient(b[0] - 5, b[1] - 6, 1, b[0], b[1], r)
      gr.addColorStop(0, '#f0e6d0'); gr.addColorStop(0.65, g.buttonColour || '#c9b48d'); gr.addColorStop(1, '#8b7a58')
      ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(b[0], b[1], r, 0, 7); ctx.fill()
      ctx.fillStyle = 'rgba(60,48,30,0.55)'
      for (const [dx, dy] of [[-4.5, -4.5], [4.5, -4.5], [-4.5, 4.5], [4.5, 4.5]]) {
        ctx.beginPath(); ctx.arc(b[0] + dx, b[1] + dy, 2.1, 0, 7); ctx.fill()
      }
    }
    ctx.restore()

    // one key light, top left, so every garment sits in the same room
    ctx.save()
    unionPath(g); ctx.clip()
    ctx.globalCompositeOperation = 'screen'
    const key2 = ctx.createRadialGradient(330, 300, 60, 600, 900, 1250)
    key2.addColorStop(0, 'rgba(255,252,244,0.16)'); key2.addColorStop(1, 'rgba(255,255,255,0)')
    ctx.fillStyle = key2; ctx.fillRect(0, 0, W, H)
    ctx.globalCompositeOperation = 'multiply'
    const amb = ctx.createLinearGradient(0, 300, 0, 1500)
    amb.addColorStop(0, 'rgba(255,255,255,1)'); amb.addColorStop(1, 'rgba(146,150,162,1)')
    ctx.fillStyle = amb; ctx.globalAlpha = 0.5; ctx.fillRect(0, 0, W, H)
    ctx.restore()

    results[key] = c.toDataURL('image/png')
  }
  return results
}, { GARMENTS, cloth, W, H })

for (const [k, dataUrl] of Object.entries(out)) {
