// The loom: samples a garment image on a warp/weft grid whose cell size is the only
// thing that changes. At a coarse cell you are looking at the cloth thread by thread;
// as the cell falls to one pixel the same image resolves into the garment itself.
// Each quad is positioned from a measured DOM rectangle, so the scene lands exactly
// where the shop's markup already is.

const VERT = `#version 300 es
in vec2 a_pos;
uniform vec4 u_rect;      // x, y, w, h in CSS pixels, top-left origin
uniform vec2 u_res;
out vec2 v_a;             // 0..1 within the rect
void main() {
  v_a = a_pos;
  vec2 px = u_rect.xy + a_pos * u_rect.zw;
  vec2 clip = vec2(px.x / u_res.x * 2.0 - 1.0, 1.0 - px.y / u_res.y * 2.0);
  gl_Position = vec4(clip, 0.0, 1.0);
}`

const FRAG = `#version 300 es
precision highp float;
in vec2 v_a;
out vec4 outColor;

uniform sampler2D u_tex;
uniform vec4 u_rect;
uniform vec2 u_texSize;
uniform vec2 u_focal;
uniform float u_zoom;     // 1.0 = whole garment in frame; higher = into the cloth
uniform float u_cell;     // weave cell, in CSS pixels
uniform float u_amp;      // how much the threads still ride over and under
uniform float u_alpha;
uniform float u_dpr;
uniform float u_grain;

const float PI = 3.14159265;

// uv for a point in the rect, at the current zoom, fitting the garment when zoom = 1
vec2 uvAt(vec2 a) {
  float ra = u_rect.z / u_rect.w;
  float ta = u_texSize.x / u_texSize.y;
  vec2 range = ra > ta ? vec2(ra / ta, 1.0) : vec2(1.0, ta / ra);
  return u_focal + (a - 0.5) * range / u_zoom;
}

void main() {
  vec2 rectPx = u_rect.zw;
  vec2 px = v_a * rectPx;
  float cell = max(u_cell, 0.75);

  // how many texels one screen pixel covers right now: picks the mip that matches
  // the cell, so a coarse weave is a box average of the cloth, never aliased noise
  float ra = u_rect.z / u_rect.w;
  float ta = u_texSize.x / u_texSize.y;
  vec2 range = ra > ta ? vec2(ra / ta, 1.0) : vec2(1.0, ta / ra);
  float texelsPerPx = (u_texSize.x * range.x / u_zoom) / rectPx.x;
  float lodCoarse = max(0.0, log2(max(texelsPerPx * cell, 1.0)));
  float lodSharp = max(0.0, log2(max(texelsPerPx / u_dpr, 1.0)));

  vec2 cellId = floor(px / cell);
  vec2 f = fract(px / cell);

  // warp and weft alternate over and under; each thread also shifts along itself,
  // which is what stops the coarse state reading as a screen of square pixels
  float over = mod(cellId.x + cellId.y, 2.0);
  vec2 shift = over > 0.5
    ? vec2(0.0, sin(cellId.x * 1.73 + 0.7) * 0.42)
    : vec2(sin(cellId.y * 1.31) * 0.42, 0.0);
  vec2 samplePx = (cellId + 0.5 + shift * u_amp) * cell;

  vec4 coarse = textureLod(u_tex, uvAt(samplePx / rectPx), lodCoarse);

  // the yarn on top is round: it catches light across its width and dips where it
  // crosses under its neighbour
  float across = over > 0.5 ? f.x : f.y;
  float along  = over > 0.5 ? f.y : f.x;
  float roundness = pow(max(sin(across * PI), 0.0), 0.55);
  float dip = 0.90 + 0.16 * sin(along * PI);
  float shade = mix(1.0, (0.52 + 0.72 * roundness) * dip, u_amp);
  // the gap between threads shows the ground through the cloth
  float gap = smoothstep(0.0, 0.13, min(across, 1.0 - across));
  float openness = mix(1.0, 0.34 + 0.66 * gap, u_amp * 0.85);

  vec4 sharp = textureLod(u_tex, uvAt(v_a), lodSharp);

  float toSharp = 1.0 - smoothstep(0.9, 2.6, cell);
  vec4 col = mix(coarse, sharp, toSharp);
  col.rgb *= mix(1.0, shade, 1.0 - toSharp);
  col.a *= mix(1.0, openness, 1.0 - toSharp);

  // a little loom dust, strongest while the weave is open
  float g = fract(sin(dot(px + cellId, vec2(12.9898, 78.233))) * 43758.5453);
  col.rgb += (g - 0.5) * 0.05 * u_grain * u_amp;

  outColor = vec4(col.rgb, col.a * u_alpha);
}`

function compile(gl, type, src) {
  const s = gl.createShader(type)
  gl.shaderSource(s, src); gl.compileShader(s)
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s))
  return s
}

export function createLoom(canvas) {
  const gl = canvas.getContext('webgl2', { alpha: true, premultipliedAlpha: false, antialias: false })
  if (!gl) return null

  const prog = gl.createProgram()
  gl.attachShader(prog, compile(gl, gl.VERTEX_SHADER, VERT))
  gl.attachShader(prog, compile(gl, gl.FRAGMENT_SHADER, FRAG))
  gl.linkProgram(prog)
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog))
  gl.useProgram(prog)

  const buf = gl.createBuffer()
  gl.bindBuffer(gl.ARRAY_BUFFER, buf)
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]), gl.STATIC_DRAW)
  const loc = gl.getAttribLocation(prog, 'a_pos')
  gl.enableVertexAttribArray(loc)
  gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0)

  const U = {}
  for (const n of ['u_rect', 'u_res', 'u_texSize', 'u_focal', 'u_zoom', 'u_cell', 'u_amp', 'u_alpha', 'u_dpr', 'u_grain']) {
    U[n] = gl.getUniformLocation(prog, n)
  }

  gl.enable(gl.BLEND)
  gl.blendFuncSeparate(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA)

  const textures = new Map()
  let dpr = 1, W = 0, H = 0

  function loadTexture(key, image) {
    const t = gl.createTexture()
    gl.bindTexture(gl.TEXTURE_2D, t)
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false)
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, image)
    gl.generateMipmap(gl.TEXTURE_2D)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
    textures.set(key, { tex: t, w: image.width, h: image.height })
  }

  function resize(w, h, ratio) {
    dpr = ratio; W = w; H = h
    canvas.width = Math.round(w * ratio); canvas.height = Math.round(h * ratio)
    canvas.style.width = w + 'px'; canvas.style.height = h + 'px'
    gl.viewport(0, 0, canvas.width, canvas.height)
  }

  // quads: { key, rect:[x,y,w,h], focal:[u,v], zoom, cell, amp, alpha, grain }
  function render(quads) {
    gl.clearColor(0, 0, 0, 0)
    gl.clear(gl.COLOR_BUFFER_BIT)
    gl.uniform2f(U.u_res, W, H)
    gl.uniform1f(U.u_dpr, dpr)
    for (const q of quads) {
      const t = textures.get(q.key)
      if (!t || q.alpha <= 0.002 || q.rect[2] <= 0 || q.rect[3] <= 0) continue
      gl.bindTexture(gl.TEXTURE_2D, t.tex)
      gl.uniform4f(U.u_rect, q.rect[0], q.rect[1], q.rect[2], q.rect[3])
      gl.uniform2f(U.u_texSize, t.w, t.h)
      gl.uniform2f(U.u_focal, q.focal[0], q.focal[1])
      gl.uniform1f(U.u_zoom, q.zoom)
      gl.uniform1f(U.u_cell, q.cell)
      gl.uniform1f(U.u_amp, q.amp)
      gl.uniform1f(U.u_alpha, q.alpha)
      gl.uniform1f(U.u_grain, q.grain ?? 1)
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
    }
  }

  function dispose() {
    for (const { tex } of textures.values()) gl.deleteTexture(tex)
    textures.clear()
    gl.deleteBuffer(buf); gl.deleteProgram(prog)
    gl.getExtension('WEBGL_lose_context')?.loseContext()
  }

  return { loadTexture, resize, render, dispose }
}

import { useEffect, useRef, useState } from 'react'
import { createLoom } from './loom.js'

// The signature moment. One scroll progress drives it end to end:
//   0.00 inside the cloth, thread by thread
//   0.14 the weave closes up while an editorial frame draws in around the garment
//   0.56 held: the Chore Jacket, sharp, beside its name
//   0.74 the frame hands itself to the first tile of the shop
//   0.80 the rest of the row arrives still woven and resolves in place
// Every destination is a measured DOM rectangle, so the scene lands on the real markup.

export const ROW = [
  { id: 'chore', src: '/garment-chore.png', name: 'Chore Jacket', category: 'Outerwear', price: 165, fabric: '12oz cotton canvas, unlined' },
  { id: 'oxford', src: '/garment-oxford.png', name: 'The Oxford Shirt', category: 'Shirts', price: 78, fabric: '100% long-staple cotton oxford, 140gsm' },
  { id: 'jean', src: '/garment-jean.png', name: 'Straight Jean', category: 'Trousers', price: 98, fabric: '13.5oz rigid cotton denim, selvedge' },
  { id: 'knit', src: '/garment-knit.png', name: 'Lambswool Crew', category: 'Knitwear', price: 135, fabric: '100% lambswool, spun in Scotland' },
]

const clamp = (v, a = 0, b = 1) => (v < a ? a : v > b ? b : v)
const range = (p, a, b) => clamp((p - a) / (b - a || 1))
const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)
const easeOut = (t) => 1 - Math.pow(1 - t, 3)
const mix = (a, b, t) => a + (b - a) * t
const mixRect = (a, b, t) => [mix(a[0], b[0], t), mix(a[1], b[1], t), mix(a[2], b[2], t), mix(a[3], b[3], t)]

export default function LoomScene() {
  const sectionRef = useRef(null)
  const stageRef = useRef(null)
  const canvasRef = useRef(null)
  const frameRef = useRef(null)
  const mediaRefs = useRef([])
  const heroTypeRef = useRef(null)
  const captionRef = useRef(null)
  const shopRef = useRef(null)

  const [ready, setReady] = useState(false)
  const [still, setStill] = useState(false)   // reduced motion, or no WebGL2

  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const stage = stageRef.current
    const canvas = canvasRef.current
    let loom = null
    let raf = 0, alive = true
    let target = 0, current = 0, last = performance.now(), settled = false
    let handedOff = null

    const goStill = () => { setStill(true); setReady(true) }
    if (mq.matches) { goStill(); return }

    loom = createLoom(canvas)
    if (!loom) { goStill(); return }

    let cancelled = false
    Promise.all(ROW.map((g) => new Promise((res, rej) => {
      const img = new Image()
      img.onload = () => res([g.id, img])
      img.onerror = rej
      img.src = g.src
    }))).then((pairs) => {
      if (cancelled) return
      for (const [id, img] of pairs) loom.loadTexture(id, img)
      setReady(true)
      start()
    }).catch(goStill)

    let W = 0, H = 0
    const measure = () => {
      W = window.innerWidth; H = window.innerHeight
      loom.resize(W, H, Math.min(window.devicePixelRatio || 1, 2))
      settled = false
    }

    const rectOf = (el) => {
      const r = el.getBoundingClientRect()
      return [r.left, r.top, r.width, r.height]
    }

    const draw = (p) => {
      const frame = rectOf(frameRef.current)
      const tiles = mediaRefs.current.map(rectOf)
      const full = [0, 0, W, H]

      // hero: cloth -> framed garment -> the first tile of the shop
      const open = easeInOut(range(p, 0.14, 0.56))
      const flip = easeInOut(range(p, 0.74, 0.93))
      let rect = mixRect(full, frame, open)
      rect = mixRect(rect, tiles[0], flip)

      const zoom = mix(6.5, 1.0, easeOut(range(p, 0.0, 0.60)))
      const cellP = easeInOut(range(p, 0.08, 0.62))
      const quads = [{
        key: ROW[0].id,
        rect,
        focal: [mix(0.415, 0.5, easeInOut(range(p, 0, 0.6))), mix(0.60, 0.5, easeInOut(range(p, 0, 0.6)))],
        zoom: mix(zoom, 1.0, flip),
        cell: mix(30, 1, cellP),
        amp: 1 - easeInOut(range(p, 0.06, 0.60)),
        alpha: 1 - range(p, 0.985, 1.0),
        grain: 1,
      }]

      // the rest of the row arrives woven and resolves where it lands
      for (let i = 1; i < ROW.length; i++) {
        const stagger = (i - 1) * 0.035
        const rise = easeOut(range(p, 0.78 + stagger, 0.95 + stagger))
        const r = tiles[i].slice()
        r[1] += (1 - rise) * 64
        quads.push({
          key: ROW[i].id,
          rect: r,
          focal: [0.5, 0.5],
          zoom: 1,
          cell: mix(26, 1, easeInOut(range(p, 0.80 + stagger, 0.97 + stagger))),
          amp: 1 - easeInOut(range(p, 0.80 + stagger, 0.95 + stagger)),
          alpha: range(p, 0.78 + stagger, 0.88 + stagger) * (1 - range(p, 0.985, 1.0)),
          grain: 0.6,
        })
      }
      loom.render(quads)

      // ground: the shop arrives in daylight, the cloth was seen in the dark
      stage.style.setProperty('--ground', String(easeInOut(range(p, 0.30, 0.58))))
      stage.style.setProperty('--frame-in', String(range(p, 0.16, 0.30)))
      heroTypeRef.current.style.setProperty('--in', String(range(p, 0.04, 0.16) * (1 - range(p, 0.42, 0.54))))
      captionRef.current.style.setProperty('--in', String(range(p, 0.56, 0.66) * (1 - range(p, 0.72, 0.80))))
      shopRef.current.style.setProperty('--in', String(range(p, 0.80, 0.94)))

      // hand the row to the real markup once it has landed, so the shop is DOM again
      const done = p > 0.985
      if (done !== handedOff) {
        handedOff = done
        stage.classList.toggle('is-handed-off', done)
      }
    }

    const onScroll = () => {
      const el = sectionRef.current
      if (!el) return
      const r = el.getBoundingClientRect()
      const travel = r.height - window.innerHeight
      target = clamp(travel > 0 ? -r.top / travel : 0)
      if (settled) { settled = false; last = performance.now(); raf = raf || requestAnimationFrame(tick) }
    }

    const tick = (now) => {
      raf = 0
      if (!alive) return
      const dt = Math.min((now - last) / 1000, 0.1)
      last = now
      // time-based damping: fast scrolling still tracks, small moves stay smooth
      current += (target - current) * (1 - Math.exp(-dt / 0.055))
      if (Math.abs(target - current) < 0.0004) { current = target; settled = true }
      draw(current)
      if (!settled) raf = requestAnimationFrame(tick)
    }

    function start() {
      measure()
      onScroll()
      current = target
      draw(current)
      window.addEventListener('scroll', onScroll, { passive: true })
      window.addEventListener('resize', onResize)
    }
    const onResize = () => { measure(); onScroll(); current = target; draw(current) }

    return () => {
      cancelled = true; alive = false
      cancelAnimationFrame(raf)
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onResize)
      loom?.dispose()
    }
  }, [])

  return (
    <section className={`loom${still ? ' loom--still' : ''}${ready ? ' is-ready' : ''}`} ref={sectionRef}>
      <div className="loom__stage" ref={stageRef}>
        <canvas className="loom__canvas" ref={canvasRef} aria-hidden="true" />

        <div className="loom__frame" ref={frameRef} aria-hidden="true" />

        <div className="loom__hero" ref={heroTypeRef}>
          <p className="loom__eyebrow">Marlow &amp; Vale — Autumn</p>
          <h1 className="loom__title">Cloth<span>first,</span><em>then</em> the garment</h1>
          <p className="loom__lede">
            You are looking at 12oz cotton canvas at the width of a thread. Keep scrolling
            and the weave closes up into the jacket it was cut into.
          </p>
        </div>

        <figure className="loom__caption" ref={captionRef}>
          <figcaption>
            <span className="loom__cat">Outerwear</span>
            <span className="loom__name">Chore Jacket</span>
            <span className="loom__fab">12oz cotton canvas, unlined. Indigo or Sand.</span>
            <span className="loom__price">£165</span>
          </figcaption>
        </figure>

        <div className="loom__shop" ref={shopRef}>
          <div className="shop__head">
            <h2>The shop</h2>
            <p>Nine garments, one price all year.</p>
          </div>
          <ul className="shop__row">
            {ROW.map((g, i) => (
              <li className="tile" key={g.id}>
                <div className="tile__media" ref={(el) => { mediaRefs.current[i] = el }}>
                  <img src={g.src} alt={`${g.name}, shown as a flat lay in ${g.fabric}`} />
                </div>
                <div className="tile__meta">
                  <span className="tile__name">{g.name}</span>
                  <span className="tile__cat">{g.category}</span>
                  <span className="tile__price">£{g.price}</span>
                </div>
              </li>
            ))}
          </ul>
          <p className="shop__note">
            Garment images are made from the cloth each piece is cut from. They represent the
            garments; they are not photographs of stock.
          </p>
        </div>
      </div>
    </section>
  )
}

/* Marlow & Vale — signature moment slice.
   Only the loom scene and the row it hands the shop to are styled here. */

:root {
  --ink: #10131a;
  --ink-2: #1b2029;
  --paper: #e9e5dd;
  --paper-2: #f3f0ea;
  --indigo: #2f4360;
  --thread: #c2a878;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans: Inter, "Helvetica Neue", Arial, system-ui, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: auto; }

body {
  margin: 0;
  background: var(--ink);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
}

/* ---------------------------------------------------------------- the scene */

.loom {
  position: relative;
  height: 340vh;
  background: var(--ink);
}

.loom__stage {
  position: sticky;
  top: 0;
  height: 100vh;
  overflow: hidden;
  isolation: isolate;
}

/* the ground the cloth is seen against: dark at thread scale, daylight in the shop */
.loom__stage::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--ink);
  z-index: 0;
}
.loom__stage::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 90% at 18% 8%, var(--paper-2), transparent 60%),
    var(--paper);
  opacity: var(--ground, 1);
  z-index: 0;
}

.loom:not(.loom--still) .loom__stage { --ground: 0; }
.loom:not(.loom--still) .loom__hero,
.loom:not(.loom--still) .loom__caption,
.loom:not(.loom--still) .loom__shop { --in: 0; }

.loom__canvas {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

/* the editorial frame the garment is pulled into: a measured rectangle,
   with a hairline that draws itself in as the weave closes */
.loom__frame {
  position: absolute;
  left: 6.5vw;
  top: 11vh;
  width: min(37vw, 520px);
  aspect-ratio: 3 / 4;
  z-index: 2;
}
.loom__frame::before,
.loom__frame::after {
  content: "";
  position: absolute;
  background: rgba(16, 19, 26, 0.28);
  opacity: var(--frame-in, 1);
}
.loom__frame::before { left: -18px; top: -18px; width: 1px; height: calc(100% + 36px); transform-origin: top; transform: scaleY(var(--frame-in, 1)); }
.loom__frame::after { left: -18px; top: -18px; height: 1px; width: calc(100% + 36px); transform-origin: left; transform: scaleX(var(--frame-in, 1)); }
.loom__frame img { display: none; }

/* --------------------------------------------------------------- hero type */

.loom__hero {
  position: absolute;
  right: 6.5vw;
  top: 16vh;
  width: min(38vw, 470px);
  z-index: 4;
  color: var(--paper);
  opacity: var(--in, 1);
  transform: translateY(calc((1 - var(--in, 1)) * 14px));
}

.loom__eyebrow {
  margin: 0 0 22px;
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(233, 229, 221, 0.62);
}

.loom__title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(38px, 4.6vw, 72px);
  line-height: 0.96;
  letter-spacing: -0.02em;
}
.loom__title span { display: block; }
.loom__title em {
  font-style: italic;
  color: var(--thread);
}

.loom__lede {
  margin: 26px 0 0;
  max-width: 34ch;
  font-size: 15px;
  line-height: 1.62;
  color: rgba(233, 229, 221, 0.72);
}

/* -------------------------------------------- the held state, read at rest */

.loom__caption {
  position: absolute;
  left: calc(6.5vw + min(37vw, 520px) + 56px);
  top: 30vh;
  margin: 0;
  z-index: 4;
  opacity: var(--in, 1);
  transform: translateY(calc((1 - var(--in, 1)) * 10px));
}
.loom__caption figcaption { display: grid; gap: 10px; }
.loom__cat {
  font-size: 11px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(16, 19, 26, 0.5);
}
.loom__name {
  font-family: var(--serif);
  font-size: clamp(30px, 3.4vw, 52px);
  line-height: 1;
  letter-spacing: -0.02em;
}
.loom__fab {
  max-width: 26ch;
  font-size: 14px;
  line-height: 1.6;
  color: rgba(16, 19, 26, 0.66);
}
.loom__price {
  margin-top: 6px;
  font-size: 15px;
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------- the arrival */

.loom__shop {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: clamp(18px, 3vh, 34px);
  padding: 8vh 5vw;
}

.shop__head {
  display: flex;
  align-items: baseline;
  gap: 20px;
  opacity: var(--in, 1);
  transform: translateY(calc((1 - var(--in, 1)) * 12px));
}
.shop__head h2 {
  margin: 0;
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(22px, 2.2vw, 32px);
  letter-spacing: -0.01em;
}
.shop__head p {
  margin: 0;
  font-size: 13px;
  color: rgba(16, 19, 26, 0.58);
}

.shop__row {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(16px, 2vw, 28px);
}

.tile__media {
  position: relative;
  aspect-ratio: 3 / 4;
  background: rgba(16, 19, 26, 0.035);
  overflow: hidden;
}
.tile__media img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  opacity: 0;
}
/* the canvas has landed the row exactly here, so the swap to real markup is invisible */
.is-handed-off .tile__media img { opacity: 1; }

.tile__meta {
  display: grid;
  gap: 3px;
  margin-top: 14px;
  opacity: var(--in, 1);
}
.tile__name { font-size: 15px; letter-spacing: -0.01em; }
.tile__cat {
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(16, 19, 26, 0.45);
}
.tile__price { font-size: 14px; font-variant-numeric: tabular-nums; }

.shop__note {
  margin: 0;
  max-width: 58ch;
  font-size: 11.5px;
  line-height: 1.6;
  color: rgba(16, 19, 26, 0.45);
  opacity: var(--in, 1);
}

/* --------------------------------------------- reduced motion / no WebGL2 */

.loom--still { height: auto; }
.loom--still .loom__stage { position: static; height: auto; padding-bottom: 6vh; }
.loom--still .loom__canvas { display: none; }
.loom--still .loom__frame {
  position: relative;
  left: 0; top: 0;
  margin: 0 6.5vw;
  width: min(37vw, 520px);
}
.loom--still .loom__frame img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.loom--still .loom__hero,
.loom--still .loom__caption {
  position: relative;
  right: auto; left: auto; top: auto;
  width: auto;
  padding: 0 6.5vw;
}
.loom--still .loom__hero { color: var(--ink); padding-top: 8vh; padding-bottom: 4vh; }
.loom--still .loom__eyebrow { color: rgba(16, 19, 26, 0.55); }
.loom--still .loom__lede { color: rgba(16, 19, 26, 0.68); }
.loom--still .loom__caption { margin-top: 32px; }
.loom--still .loom__shop { position: relative; inset: auto; padding: 8vh 5vw; }
.loom--still .tile__media img { opacity: 1; }
.loom--still .loom__stage::after { opacity: 1; }

/* --------------------------------------------------------------- the exit */

.after {
  position: relative;
  z-index: 5;
  background: var(--paper);
  color: var(--ink);
  padding: 12vh 6.5vw 16vh;
  border-top: 1px solid rgba(16, 19, 26, 0.12);
}
.after p {
  margin: 0 0 14px;
  max-width: 60ch;
  font-size: 14px;
  line-height: 1.7;
  color: rgba(16, 19, 26, 0.62);
}
.after h2 {
  margin: 0 0 20px;
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(24px, 2.6vw, 38px);
}

/* ------------------------------------------------------------------ mobile */

@media (max-width: 860px) {
  .loom { height: 320vh; }
  .loom__frame {
    left: 50%;
    transform: translateX(-50%);
    top: 8vh;
    width: min(74vw, 420px);
  }
  .loom__hero {
    right: auto;
    left: 6vw;
    top: auto;
    bottom: 6vh;
    width: 88vw;
  }
  .loom__lede { display: none; }
  .loom__caption {
    left: 6vw;
    top: auto;
    bottom: 8vh;
  }
  .loom__shop { padding: 6vh 6vw; justify-content: center; }
  .shop__row { grid-template-columns: repeat(2, 1fr); gap: 14px 16px; }
  .shop__note { display: none; }
  .loom--still .loom__frame { margin: 0 auto; transform: none; left: auto; }
  .loom--still .loom__hero, .loom--still .loom__caption { bottom: auto; left: auto; }
}

