  const c = document.createElement('canvas');
  const gl = c.getContext('webgl2');
  const out = {};
  for (const [name, type] of [['VERT', gl.VERTEX_SHADER], ['FRAG', gl.FRAGMENT_SHADER]]) {
    const text = grab(name);
