import { useEffect, useRef, useState, useId } from 'react'

// Which cloth each garment is shown in. The pictures are made from the fabric the
// garment is cut from; they represent the garments and are not photographs of stock.
export const MEDIA = {
  oxford: { src: '/garment-oxford.png', shown: 'Pale blue' },
  tee: { src: '/garment-tee.png', shown: 'White' },
  chore: { src: '/garment-chore.png', shown: 'Indigo' },
  overshirt: { src: '/garment-overshirt.png', shown: 'Charcoal' },
  trouser: { src: '/garment-trouser.png', shown: 'Stone' },
  jean: { src: '/garment-jean.png', shown: 'Rinse' },
  knit: { src: '/garment-knit.png', shown: 'Navy' },
  cardigan: { src: '/garment-cardigan.png', shown: 'Charcoal' },
  shorts: { src: '/garment-shorts.png', shown: 'Khaki' },
}

export const money = (n) => `£${n.toFixed(2).replace(/\.00$/, '')}`

/* ------------------------------------------------------------------ reveal */
// Sections arrive the way the cloth does: they settle rather than pop. One observer,
// one class, and nothing at all when the visitor has asked for reduced motion.
export function useReveal() {
  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      document.querySelectorAll('.reveal').forEach((el) => el.classList.add('is-in'))
      return
    }
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target) }
      }
    }, { rootMargin: '0px 0px -12% 0px', threshold: 0.08 })
    const seen = new Set()
    const scan = () => {
      document.querySelectorAll('.reveal:not(.is-in)').forEach((el) => {
        if (!seen.has(el)) { seen.add(el); io.observe(el) }
      })
    }
    scan()
    const mo = new MutationObserver(scan)
    mo.observe(document.body, { childList: true, subtree: true })
    return () => { io.disconnect(); mo.disconnect() }
  }, [])
}

/* -------------------------------------------------------------------- header */

export function SiteHeader({ bagCount, onOpenBag, subtotal }) {
  const [solid, setSolid] = useState(false)
  const [bump, setBump] = useState(false)
  const first = useRef(true)

  useEffect(() => {
    const onScroll = () => setSolid(window.scrollY > window.innerHeight * 0.9)
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  useEffect(() => {
    if (first.current) { first.current = false; return }
    setBump(true)
    const t = setTimeout(() => setBump(false), 420)
    return () => clearTimeout(t)
  }, [bagCount])

  return (
    <header className={`site${solid ? ' site--solid' : ''}`}>
      <a className="site__mark" href="#top">
        Marlow <span>&amp;</span> Vale
      </a>
      <nav className="site__nav" aria-label="Sections">
        <a href="#shop">Shop</a>
        <a href="#fit">Size &amp; fit</a>
        <a href="#care">Care</a>
        <a href="#delivery">Delivery</a>
        <a href="#about">The shop</a>
      </nav>
      <button
        type="button"
        className={`site__bag${bump ? ' is-bumped' : ''}`}
        onClick={onOpenBag}
        aria-haspopup="dialog"
      >
        Bag
        <span className="site__count" aria-hidden="true">{bagCount}</span>
        <span className="visually-hidden">
          {bagCount === 1 ? '1 item' : `${bagCount} items`}
          {bagCount > 0 ? `, subtotal ${money(subtotal)}` : ''}
        </span>
      </button>
    </header>
  )
}

/* ------------------------------------------------------------------ filters */

export function Filters({ categories, counts, total, category, setCategory, shown }) {
  return (
    <div className="filters">
      <div className="filters__bar" role="group" aria-label="Filter by category">
        <button
          type="button"
          className={`chip${category === 'All' ? ' is-on' : ''}`}
          aria-pressed={category === 'All'}
          onClick={() => setCategory('All')}
        >
          All <span className="chip__n">{total}</span>
        </button>
        {categories.map((c) => (
          <button
            key={c}
            type="button"
            className={`chip${category === c ? ' is-on' : ''}`}
            aria-pressed={category === c}
            onClick={() => setCategory(c)}
          >
            {c} <span className="chip__n">{counts[c]}</span>
          </button>
        ))}
      </div>
      <p className="filters__count" aria-live="polite">
        Showing {shown} of {total} garments{category === 'All' ? '' : ` in ${category}`}.
      </p>
    </div>
  )
}

/* --------------------------------------------------------------------- card */

export function Card({ garment, sizes, chosen, onChoose, onAdd, justAdded }) {
  const media = MEDIA[garment.id]
  const nameId = useId()
  const size = chosen
  const soldOut = size ? garment.sold.includes(size) : false

  return (
    <li className="card reveal" id={`g-${garment.id}`}>
      <div className="card__media" data-weave={garment.id} data-src={media.src}>
        <img
          src={media.src}
          alt={`${garment.name}, laid flat, shown in ${media.shown}`}
          loading="lazy"
          decoding="async"
        />
        <span className="card__cloth" aria-hidden="true">{garment.fabric.split(',')[0]}</span>
      </div>

      <div className="card__body">
        <div className="card__line">
          <h3 className="card__name" id={nameId}>{garment.name}</h3>
          <span className="card__price">£{garment.price}</span>
        </div>
        <p className="card__cat">{garment.category}</p>
        <p className="card__detail">{garment.detail}</p>
        <p className="card__fabric">{garment.fabric}</p>
        <p className="card__colours">
          <span>Colours</span> {garment.colours.join(', ')}
          <span className="card__shownin">Shown in {media.shown}</span>
        </p>

        <div className="sizes" role="group" aria-labelledby={nameId}>
          {sizes.map((s) => {
            const gone = garment.sold.includes(s)
            return (
              <button
                key={s}
                type="button"
                className={`size${chosen === s ? ' is-on' : ''}${gone ? ' is-gone' : ''}`}
                disabled={gone}
                aria-pressed={chosen === s}
                onClick={() => onChoose(garment.id, s)}
              >
                {s}
                {gone && <span className="visually-hidden"> — sold out</span>}
              </button>
            )
          })}
        </div>

        <p className="sizes__state" aria-live="polite">
          {chosen
            ? (soldOut ? `Size ${chosen} is sold out` : `Size ${chosen} chosen`)
            : 'No size chosen yet'}
          {garment.sold.length > 0 && (
            <span className="sizes__gone"> · {garment.sold.join(' and ')} sold out</span>
          )}
        </p>

        <button
          type="button"
          className={`add${justAdded ? ' is-added' : ''}`}
          disabled={!chosen || soldOut}
          onClick={() => onAdd(garment)}
        >
          <span>{justAdded ? 'Added to bag' : 'Add to bag'}</span>
        </button>
      </div>
    </li>
  )
}

/* ---------------------------------------------------------------------- bag */

export function BagDrawer({ open, onClose, bag, remove, total, postage }) {
  const panel = useRef(null)
  const closeBtn = useRef(null)
  const opener = useRef(null)

  useEffect(() => {
    if (open) {
      opener.current = document.activeElement
      closeBtn.current?.focus()
      const onKey = (e) => {
        if (e.key === 'Escape') { e.stopPropagation(); onClose() }
        if (e.key === 'Tab' && panel.current) {
          const f = panel.current.querySelectorAll('button, a[href], input')
          if (!f.length) return
          const first = f[0], last = f[f.length - 1]
          if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus() }
          else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus() }
        }
      }
      document.addEventListener('keydown', onKey)
      document.body.style.overflow = 'hidden'
      return () => { document.removeEventListener('keydown', onKey); document.body.style.overflow = '' }
    }
    opener.current?.focus?.()
  }, [open, onClose])

  const shortfall = 100 - total

  return (
    <div className={`bag${open ? ' is-open' : ''}`} aria-hidden={!open}>
      <button className="bag__scrim" type="button" tabIndex={-1} aria-hidden="true" onClick={onClose} />
      <div
        className="bag__panel"
        role="dialog"
        aria-modal="true"
        aria-label="Your bag"
        ref={panel}
      >
        <div className="bag__head">
          <h2>Your bag</h2>
          <button type="button" className="bag__close" onClick={onClose} ref={closeBtn}>
            Close<span aria-hidden="true"> ×</span>
          </button>
        </div>

        {bag.length === 0 ? (
          <p className="bag__empty">Your bag is empty.</p>
        ) : (
          <>
            <ul className="bag__lines">
              {bag.map((line, i) => (
                <li className="bag__line" key={`${line.id}-${i}`}>
                  <span className="bag__thumb" aria-hidden="true">
                    <img src={MEDIA[line.id].src} alt="" />
                  </span>
                  <span className="bag__meta">
                    <span className="bag__name">{line.name}</span>
                    <span className="bag__size">Size {line.size}</span>
                  </span>
                  <span className="bag__price">£{line.price}</span>
                  <button type="button" className="bag__remove" onClick={() => remove(i)}>
                    Remove<span className="visually-hidden"> {line.name}, size {line.size}</span>
                  </button>
                </li>
              ))}
            </ul>

            <div className="bag__sums" aria-live="polite">
              <p className="bag__row"><span>Subtotal</span><span>£{total.toFixed(2)}</span></p>
              <p className="bag__row bag__row--note">
                {postage === 0
                  ? <span>Delivery free</span>
                  : <span>Delivery £{postage.toFixed(2)} — £{shortfall.toFixed(2)} more for free delivery</span>}
                {postage !== 0 && (
                  <span className="bag__gauge" aria-hidden="true">
                    <span style={{ transform: `scaleX(${Math.max(0.02, Math.min(1, total / 100))})` }} />
                  </span>
                )}
              </p>
              <p className="bag__row bag__row--total"><span>Total</span><span>£{(total + postage).toFixed(2)}</span></p>
            </div>

            <button type="button" className="bag__checkout">Checkout</button>
            <p className="bag__small">
              Free delivery on orders over £100, otherwise £4.95. 60 days to return anything
              unworn with its tags on.
            </p>
          </>
        )}
      </div>
    </div>
  )
}

import { useEffect } from 'react'

// Section entrances. One observer for the whole page: anything marked [data-reveal]
// rises into place the first time it is seen, and stays put afterwards.
// Under reduced motion the CSS resolves it instantly, so this only adds the class.
export function useReveal(deps = []) {
  useEffect(() => {
    const els = Array.from(document.querySelectorAll('[data-reveal]:not(.is-in)'))
    if (!els.length) return
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue
        e.target.classList.add('is-in')
        io.unobserve(e.target)
      }
    }, { rootMargin: '0px 0px -10% 0px', threshold: 0.08 })
    for (const el of els) io.observe(el)
    return () => io.disconnect()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
}

export function prefersReducedMotion() {
  return typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

import { useEffect, useRef } from 'react'
import { createLoom } from './loom.js'

// The shop grid inherits the hero's mechanism. Every product image arrives on the
// same loom: coarse cell first, then the weave closes and the real <img> takes over
// at exactly the same rectangle. Filtering re-runs it, so a category change is felt
// as cloth being run off again rather than as a list swap.

const DURATION = 900
const ease = (t) => 1 - Math.pow(1 - t, 3)

export default function WeaveGrid({ sources, version }) {
  const canvasRef = useRef(null)
  const loomRef = useRef(null)
  const activeRef = useRef(new Map())   // element -> { key, start }
  const rafRef = useRef(0)

  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
    const canvas = canvasRef.current
    const loom = createLoom(canvas)
    if (!loom) return
    loomRef.current = loom
    let alive = true

    const size = () => loom.resize(window.innerWidth, window.innerHeight, Math.min(window.devicePixelRatio || 1, 2))
    size()

    let loaded = 0
    for (const [key, src] of Object.entries(sources)) {
      const img = new Image()
      img.onload = () => { if (alive) { loom.loadTexture(key, img); loaded++ } }
      img.src = src
    }
    document.documentElement.classList.add('weave-on')

    const frame = () => {
      rafRef.current = 0
      if (!alive) return
      const now = performance.now()
      const quads = []
      for (const [el, state] of activeRef.current) {
        const r = el.getBoundingClientRect()
        const t = Math.min(1, (now - state.start) / DURATION)
        const e = ease(t)
        if (t >= 1 || r.bottom < -200 || r.top > window.innerHeight + 200) {
          el.classList.remove('is-woven')
          activeRef.current.delete(el)
          continue
        }
        quads.push({
          key: state.key,
          rect: [r.left, r.top, r.width, r.height],
          focal: [0.5, 0.5],
          zoom: 1,
          cell: 1 + (16 - 1) * (1 - e),
          amp: 1 - e,
          alpha: Math.min(1, t * 4),
          grain: 0.5,
        })
      }
      loom.render(quads)
      if (activeRef.current.size) rafRef.current = requestAnimationFrame(frame)
      else loom.render([])
    }
    const kick = () => { if (!rafRef.current) rafRef.current = requestAnimationFrame(frame) }

    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue
        const el = e.target
        io.unobserve(el)
        if (el.dataset.woven === 'done') continue
        el.dataset.woven = 'done'
        if (!loaded) continue                       // textures not in yet: show the image
        el.classList.add('is-woven')
        activeRef.current.set(el, { key: el.dataset.weave, start: performance.now() + Math.random() * 90 })
        kick()
      }
    }, { threshold: 0.15 })

    const scan = () => {
      for (const el of document.querySelectorAll('[data-weave]')) {
        if (el.dataset.woven !== 'done') io.observe(el)
      }
    }
    // give textures a moment so the first screenful weaves rather than pops
    const t0 = setTimeout(scan, 260)
    window.addEventListener('resize', size)

    return () => {
      alive = false
      clearTimeout(t0)
      cancelAnimationFrame(rafRef.current)
      rafRef.current = 0
      window.removeEventListener('resize', size)
      io.disconnect()
      for (const [el] of activeRef.current) el.classList.remove('is-woven')
      activeRef.current.clear()
      document.documentElement.classList.remove('weave-on')
      loom.dispose()
      loomRef.current = null
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // a filter change produces new media elements: weave them in too
  useEffect(() => {
    if (!loomRef.current) return
    const id = setTimeout(() => {
      const loom = loomRef.current
      if (!loom) return
      const now = performance.now()
      let i = 0
      for (const el of document.querySelectorAll('[data-weave]')) {
        const r = el.getBoundingClientRect()
        if (r.bottom < 0 || r.top > window.innerHeight) continue
        el.dataset.woven = 'done'
        el.classList.add('is-woven')
        activeRef.current.set(el, { key: el.dataset.weave, start: now + (i++) * 45 })
      }
      if (activeRef.current.size && !rafRef.current) {
        rafRef.current = requestAnimationFrame(function step() {
          rafRef.current = 0
          const t = performance.now()
          const quads = []
          for (const [el, state] of activeRef.current) {
            const r = el.getBoundingClientRect()
            const p = Math.min(1, Math.max(0, (t - state.start) / DURATION))
            if (p >= 1) { el.classList.remove('is-woven'); activeRef.current.delete(el); continue }
            const e = ease(p)
            quads.push({
              key: state.key, rect: [r.left, r.top, r.width, r.height], focal: [0.5, 0.5],
              zoom: 1, cell: 1 + 15 * (1 - e), amp: 1 - e, alpha: Math.min(1, p * 4), grain: 0.5,
            })
          }
          loom.render(quads)
          if (activeRef.current.size) rafRef.current = requestAnimationFrame(step)
          else loom.render([])
        })
      }
    }, 16)
    return () => clearTimeout(id)
  }, [version])

  return <canvas className="weavegrid" ref={canvasRef} aria-hidden="true" />
}

import { useEffect, useRef } from 'react'
import { createLoom } from './loom.js'

// The shop grid speaks the same language as the hero. A card's picture arrives on the
// loom — coarse threads first — and closes up into the garment where it sits. Same
// renderer, same measured-rectangle rule; only the driver differs, because a filter
// change has no scroll to hang off. Once a card has resolved it stays resolved, and
// the canvas hands the picture back to the real <img>.

const DUR = 820
const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)
const mix = (a, b, t) => a + (b - a) * t

export default function WeaveGrid() {
  const canvasRef = useRef(null)

  useEffect(() => {
    const canvas = canvasRef.current
    const resolveAll = () => {
      document.querySelectorAll('[data-weave]').forEach((el) => { el.dataset.resolved = '1' })
    }
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      resolveAll()
      const mo = new MutationObserver(resolveAll)
      mo.observe(document.body, { childList: true, subtree: true })
      return () => mo.disconnect()
    }

    const loom = createLoom(canvas)
    if (!loom) { resolveAll(); return }

    const loaded = new Map()      // key -> 'loading' | 'ready'
    const active = new Map()      // element -> { key, start }
    let raf = 0, alive = true, queued = 0
    let W = 0, H = 0

    const measure = () => {
      W = window.innerWidth; H = window.innerHeight
      loom.resize(W, H, Math.min(window.devicePixelRatio || 1, 2))
    }
    measure()

    // grid pictures are shown small, so upload them small: nine full-size textures
    // would cost far more memory than the grid can ever show
    const upload = (key, src) => {
      if (loaded.has(key)) return
      loaded.set(key, 'loading')
      const img = new Image()
      img.decoding = 'async'
      img.onload = () => {
        const c = document.createElement('canvas')
        c.width = 600; c.height = 800
        const cx = c.getContext('2d')
        cx.drawImage(img, 0, 0, c.width, c.height)
        loom.loadTexture(key, c)
        loaded.set(key, 'ready')
        if (!raf && active.size) raf = requestAnimationFrame(tick)
      }
      img.onerror = () => loaded.delete(key)
      img.src = src
    }

    const begin = (el) => {
      if (el.dataset.resolved || active.has(el)) return
      const key = el.dataset.weave
      upload(key, el.dataset.src)
      // a short stagger so a row of cards reads as a sequence, not a flash
      active.set(el, { key, start: performance.now() + (queued++ % 4) * 70 })
      if (!raf) raf = requestAnimationFrame(tick)
    }

    const tick = (now) => {
      raf = 0
      if (!alive) return
      const quads = []
      for (const [el, state] of active) {
        const t = Math.max(0, Math.min(1, (now - state.start) / DUR))
        const r = el.getBoundingClientRect()
        if (loaded.get(state.key) !== 'ready') continue
        if (r.bottom < -200 || r.top > H + 200) {           // scrolled away mid-weave
          el.dataset.resolved = '1'; active.delete(el); continue
        }
        const e = easeInOut(t)
        quads.push({
          key: state.key,
          rect: [r.left, r.top, r.width, r.height],
          focal: [0.5, 0.5],
          zoom: 1,
          cell: mix(16, 1, e),
          amp: 1 - e,
          alpha: Math.min(1, t / 0.12),
          grain: 0.5,
        })
        if (t >= 1) { el.dataset.resolved = '1'; active.delete(el) }
      }
      loom.render(quads)
      if (active.size) raf = requestAnimationFrame(tick)
      else loom.render([])
    }

    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (e.isIntersecting) { begin(e.target); io.unobserve(e.target) }
      }
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.15 })

    const seen = new WeakSet()
    const scan = () => {
      document.querySelectorAll('[data-weave]:not([data-resolved])').forEach((el) => {
        if (!seen.has(el)) { seen.add(el); io.observe(el) }
      })
    }
    scan()
    const mo = new MutationObserver(() => { queued = 0; scan() })
    mo.observe(document.body, { childList: true, subtree: true })

    const onResize = () => measure()
    window.addEventListener('resize', onResize)
    const onScroll = () => { if (active.size && !raf) raf = requestAnimationFrame(tick) }
    window.addEventListener('scroll', onScroll, { passive: true })

    return () => {
      alive = false
      cancelAnimationFrame(raf)
      io.disconnect(); mo.disconnect()
      window.removeEventListener('resize', onResize)
      window.removeEventListener('scroll', onScroll)
      loom.dispose()
    }
  }, [])

  return <canvas className="weavegrid" ref={canvasRef} aria-hidden="true" />
}

import { useEffect, useRef, useState } from 'react'
import { MEDIA, altFor } from './media.js'

/* ------------------------------------------------------------------ header */

export function SiteHeader({ bagCount, onOpenBag, bagButtonRef }) {
  const [solid, setSolid] = useState(false)
  useEffect(() => {
    const onScroll = () => setSolid(window.scrollY > window.innerHeight * 2.4)
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  return (
    <header className={`site${solid ? ' site--solid' : ''}`}>
      <a className="site__mark" href="#top">
        Marlow <span>&amp;</span> Vale
      </a>
      <nav className="site__nav" aria-label="Sections">
        <a href="#shop">Shop</a>
        <a href="#fit">Size &amp; fit</a>
        <a href="#care">Care</a>
        <a href="#delivery">Delivery</a>
        <a href="#about">The shop</a>
      </nav>
      <button type="button" className="site__bag" onClick={onOpenBag} ref={bagButtonRef}>
        Bag<span className="site__count" aria-hidden="true">{bagCount}</span>
        <span className="visually-hidden">, {bagCount} item{bagCount === 1 ? '' : 's'}</span>
      </button>
    </header>
  )
}

/* -------------------------------------------------------------------- shop */

function SizeRow({ garment, sizes, chosen, onChoose }) {
  return (
    <div className="sizes" role="group" aria-label={`Size, ${garment.name}`}>
      {sizes.map((s) => {
        const gone = garment.sold.includes(s)
        const on = chosen === s
        return (
          <button
            key={s}
            type="button"
            className={`size${gone ? ' size--gone' : ''}${on ? ' is-on' : ''}`}
            disabled={gone}
            aria-pressed={on}
            aria-label={gone ? `${s}, sold out` : s}
            onClick={() => onChoose(s)}
          >
            {s}
          </button>
        )
      })}
    </div>
  )
}

export function Card({ garment, sizes, chosen, onChoose, onAdd, index }) {
  const g = garment
  const gone = chosen ? g.sold.includes(chosen) : false
  return (
    <li className="card" id={`g-${g.id}`} data-reveal style={{ '--i': index % 3 }}>
      <div className="card__media" data-weave={g.id}>
        <img src={MEDIA[g.id].src} alt={altFor(g)} loading="lazy" width="1200" height="1600" />
      </div>

      <div className="card__body">
        <div className="card__line">
          <h3 className="card__name">{g.name}</h3>
          <span className="card__price">£{g.price}</span>
        </div>
        <p className="card__cat">{g.category}</p>
        <p className="card__detail">{g.detail}</p>
        <p className="card__fabric">{g.fabric}</p>
        <p className="card__colours">
          <span>Colours</span> {g.colours.join(', ')}
          <em>Shown in {MEDIA[g.id].shown}</em>
        </p>

        <SizeRow garment={g} sizes={sizes} chosen={chosen} onChoose={onChoose} />

        <div className="card__buy">
          <button
            type="button"
            className="btn btn--add"
            disabled={!chosen || gone}
            onClick={() => onAdd(g)}
          >
            Add to bag
          </button>
          <p className="card__state" aria-live="polite">
            {chosen ? `Size ${chosen} chosen` : 'No size chosen yet'}
          </p>
        </div>
        {g.sold.length > 0 && (
          <p className="card__gone">
            Sold out in {g.sold.join(' and ')}. We do not restock mid-season.
          </p>
        )}
      </div>
    </li>
  )
}

export function Shop({
  garments, all, categories, category, onCategory, shownCount,
  sizes, chosen, onChoose, onAdd,
}) {
  return (
    <section className="shop" id="shop">
      <div className="shop__intro" data-reveal>
        <p className="eyebrow">Everything we make</p>
        <h2 className="h2">Nine garments, cut from four cloths and priced the same all year.</h2>
      </div>

      <div className="filter" role="group" aria-label="Filter by category">
        <button
          type="button"
          className={`chip${category === 'All' ? ' is-on' : ''}`}
          aria-pressed={category === 'All'}
          onClick={() => onCategory('All')}
        >
          All <span>{all.length}</span>
        </button>
        {categories.map((c) => (
          <button
            key={c}
            type="button"
            className={`chip${category === c ? ' is-on' : ''}`}
            aria-pressed={category === c}
            onClick={() => onCategory(c)}
          >
            {c} <span>{all.filter((g) => g.category === c).length}</span>
          </button>
        ))}
        <p className="filter__count" aria-live="polite">
          Showing {shownCount} of {all.length} garments{category === 'All' ? '' : ` in ${category}`}.
        </p>
      </div>

      <ul className="grid">
        {garments.map((g, i) => (
          <Card
            key={g.id}
            garment={g}
            index={i}
            sizes={sizes}
            chosen={chosen[g.id]}
            onChoose={(s) => onChoose(g.id, s)}
            onAdd={onAdd}
          />
        ))}
      </ul>
    </section>
  )
}

/* ---------------------------------------------------------------- size/fit */

export function SizeFit({ chart, advice }) {
  return (
    <section className="band band--fit" id="fit">
      <div className="band__head" data-reveal>
        <p className="eyebrow">Size and fit</p>
        <h2 className="h2">Measured on the body, in centimetres.</h2>
      </div>
      <div className="fit__table" data-reveal>
        <table>
          <caption className="visually-hidden">
            Body measurements in centimetres for each size
          </caption>
          <thead>
            <tr>
              <th scope="col">Size</th>
              <th scope="col">Chest</th>
              <th scope="col">Waist</th>
              <th scope="col">Sleeve</th>
            </tr>
          </thead>
          <tbody>
            {chart.map((row) => (
              <tr key={row.size}>
                <th scope="row">{row.size}</th>
                <td>{row.chest}</td>
                <td>{row.waist}</td>
                <td>{row.sleeve}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <p className="fit__advice">{advice}</p>
      </div>
    </section>
  )
}

/* -------------------------------------------------------------------- care */

export function Care({ facts }) {
  return (
    <section className="band band--care" id="care">
      <div className="band__head" data-reveal>
        <p className="eyebrow">Care and repair</p>
        <h2 className="h2">Four things that keep a garment going.</h2>
      </div>
      <ol className="care">
        {facts.map((line, i) => (
          <li key={line} data-reveal style={{ '--i': i % 3 }}>
            <span className="care__n">{String(i + 1).padStart(2, '0')}</span>
            <p>{line}</p>
          </li>
        ))}
      </ol>
    </section>
