export function SiteFooter() {
  return (
    <footer className="foot">
      <p className="foot__mark">Marlow &amp; Vale</p>
      <p>Leeds. Open Thursday to Sunday, eleven until six.</p>
      <p className="foot__note">
        Every garment image on this site is made from the cloth that garment is cut from.
        They represent the garments; they are not photographs of stock.
      </p>
    </footer>
  )
}

/* --------------------------------------------------------------------- bag */

export function BagDrawer({ open, onClose, bag, onRemove, total, postage, returnFocusRef }) {
  const panelRef = useRef(null)
  const closeRef = useRef(null)

  useEffect(() => {
    if (!open) return
    const onKey = (e) => {
      if (e.key === 'Escape') { e.stopPropagation(); onClose() }
      if (e.key === 'Tab') {
        const f = panelRef.current.querySelectorAll('button, a, [tabindex]:not([tabindex="-1"])')
        if (!f.length) return
        const first = f[0], last = f[f.length - 1]
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus() }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus() }
      }
    }
    closeRef.current?.focus()
    document.addEventListener('keydown', onKey)
    document.body.style.overflow = 'hidden'
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = ''
      returnFocusRef?.current?.focus()
    }
  }, [open, onClose, returnFocusRef])

  const shortfall = Math.max(0, 100 - total)

  return (
    <div className={`bag${open ? ' is-open' : ''}`} aria-hidden={!open}>
      <button
        type="button"
        className="bag__scrim"
        tabIndex={open ? 0 : -1}
        aria-label="Close the bag"
        onClick={onClose}
      />
      <div
        className="bag__panel"
        role="dialog"
        aria-modal="true"
        aria-label="Your bag"
        ref={panelRef}
      >
        <div className="bag__top">
          <h2>Your bag</h2>
          <button type="button" className="bag__close" onClick={onClose} ref={closeRef}>
            Close
          </button>
        </div>

        {bag.length === 0 ? (
          <p className="bag__empty">Your bag is empty</p>
        ) : (
          <>
            <p className="bag__count">{bag.length} item{bag.length === 1 ? '' : 's'} in the bag</p>
            <ul className="bag__lines">
              {bag.map((line, i) => (
                <li key={`${line.id}-${i}`}>
                  <span className="bag__name">{line.name}</span>
                  <span className="bag__size">Size {line.size}</span>
                  <span className="bag__price">£{line.price}</span>
                  <button type="button" className="bag__remove" onClick={() => onRemove(i)}>
                    Remove<span className="visually-hidden"> {line.name}, size {line.size}</span>
                  </button>
                </li>
              ))}
            </ul>

            <dl className="bag__sums">
              <div><dt>Subtotal</dt><dd>£{total.toFixed(2)}</dd></div>
              <div>
                <dt>Delivery</dt>
                <dd>{postage === 0 ? 'Free' : `£${postage.toFixed(2)}`}</dd>
              </div>
              <div className="bag__total"><dt>Total</dt><dd>£{(total + postage).toFixed(2)}</dd></div>
            </dl>

            <p className="bag__free" aria-live="polite">
              {postage === 0
                ? 'Delivery free'
                : `£${shortfall.toFixed(2)} more for free delivery`}
            </p>
            <div
              className="bag__meter"
              role="img"
              aria-label={postage === 0 ? 'Free delivery reached' : `${Math.round(Math.min(100, total))}% of the way to free delivery`}
            >
              <span style={{ transform: `scaleX(${Math.min(1, total / 100)})` }} />
            </div>

            <button type="button" className="btn btn--checkout">Checkout</button>
            <p className="bag__terms">
              Free delivery on orders over £100, otherwise £4.95. 60 days to return anything
              unworn with its tags on.
            </p>
          </>
        )}
      </div>
    </div>
  )
}

