async (page) => {
  await page.goto('http://127.0.0.1:5199/', { waitUntil: 'load' });
  await page.waitForTimeout(1000);
  // scrub the scene the way a wheel does and measure frame cost
  const perf = await page.evaluate(async () => {
    const sec = document.querySelector('.loom');
    const travel = sec.getBoundingClientRect().height - window.innerHeight;
    const frames = [];
    let last = performance.now();
    const onFrame = () => {
      const now = performance.now();
      frames.push(now - last); last = now;
      if (frames.length < 120) requestAnimationFrame(onFrame);
    };
    requestAnimationFrame(onFrame);
    for (let i = 0; i <= 60; i++) {
      window.scrollTo(0, (i / 60) * travel);
      await new Promise(r => setTimeout(r, 16));
    }
    await new Promise(r => setTimeout(r, 400));
    const sorted = frames.slice(10).sort((a, b) => a - b);
    return {
      n: sorted.length,
      median: +sorted[Math.floor(sorted.length / 2)].toFixed(1),
      p95: +sorted[Math.floor(sorted.length * 0.95)].toFixed(1),
      worst: +sorted[sorted.length - 1].toFixed(1),
    };
  });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  return { perf };
}

